const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const mountStanley = ee.Geometry.Point(29.8953, 0.0333).buffer(3000); // 3km buffer around Mount Stanley peak

    const start2020 = '2020-01-01';
    const end2020 = '2020-12-31';
    const start2024 = '2024-01-01';
    const end2024 = '2024-12-31'; // Or up to current date if needed.

    const scale = 30; // Sentinel-2 resolution is 10m-20m, use 30m for region reduction to be safe.

    // Function to mask clouds from Sentinel-2 surface reflectance data.
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

      // Also use SCL band to mask clouds (3, 8, 9) and shadows (3)
      const scl = image.select('SCL');
      const cloudShadowMask = scl.eq(3); // Cloud shadows
      const cloudLowMediumMask = scl.eq(8); // Clouds medium probability
      const cloudHighMask = scl.eq(9); // Clouds high probability
      const cirrusMask = scl.eq(10); // Cirrus
      const sCLMask = cloudShadowMask.or(cloudLowMediumMask).or(cloudHighMask).or(cirrusMask).not();

      return image.updateMask(mask).updateMask(sCLMask)
                  .select('B.*') // Select only band data for further processing
                  .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDSI and mask non-snow pixels
    function calculateNDSI(image) {
      const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI'); // B3=Green, B11=SWIR1
      const snowMask = ndsi.gt(0.4).and(image.select('B8').gt(0.1)); // NDSI > 0.4 and NIR > 0.1 for snow/ice
      return ndsi.updateMask(snowMask); // Only keep snow/ice pixels
    }

    // Function to get cloud-free composite and calculate snow/ice area
    async function getSnowIceArea(startDate, endDate, geometry, periodName) {
      let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                           .filterDate(startDate, endDate)
                           .filterBounds(geometry);

      const initialSize = collection.size().getInfo();
      if (initialSize === 0) {
        console.log(`${periodName} Images: 0`);
        return { area: null, count: 0, initialSize: 0 };
      }

      // Apply cloud mask and select relevant bands
      collection = collection.map(maskS2clouds);

      // Create a median composite to reduce cloud effects over the period
      const composite = collection.median();

      // If composite is empty after cloud masking, it means no valid pixels.
      // This can happen if all images are too cloudy.
      const validPixels = composite.select('B3').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('B3').getInfo();

      if (validPixels === 0 || validPixels === null) {
        console.log(`${periodName} Images: ${initialSize} (Val: 0.0)`);
        return { area: null, count: 0, initialSize: initialSize }; // No valid pixels after masking
      }

      const ndsiImage = calculateNDSI(composite);

      // Calculate the area of snow/ice pixels
      const snowIceAreaSqKm = ndsiImage.gt(0).multiply(ee.Image.pixelArea()).divide(1e6)
                               .reduceRegion({
                                 reducer: ee.Reducer.sum(),
                                 geometry: geometry,
                                 scale: scale,
                                 maxPixels: 1e9
                               }).get('NDSI').getInfo(); // Use NDSI band as a proxy for the value

      // Check if snowIceAreaSqKm is null or NaN
      if (snowIceAreaSqKm === null || isNaN(snowIceAreaSqKm)) {
        console.log(`${periodName} Images: ${initialSize} (Val: ${validPixels / (geometry.area(scale).getInfo() / (scale * scale)) * 100:.1f}%)`);
        return { area: null, count: validPixels, initialSize: initialSize }; // Calculation failure
      }

      console.log(`${periodName} Images: ${initialSize} (Val: ${(validPixels / (geometry.area(scale).getInfo() / (scale * scale)) * 100).toFixed(1)}%)`);
      return { area: snowIceAreaSqKm, count: validPixels, initialSize: initialSize };
    }

    // 2. Data Acquisition & Check for 2020
    const result2020 = await getSnowIceArea(start2020, end2020, mountStanley, '2020');
    if (result2020.initialSize === 0) {
      console.log('No data found for 2020.');
      console.log('C1');
      return;
    }
    if (result2020.count === 0) {
      console.log('No valid pixels for 2020 after cloud masking.');
      console.log('C2');
      return;
    }
    if (result2020.area === null) {
      console.log('Calculation failure for 2020 area.');
      console.log('C3');
      return;
    }

    // 2. Data Acquisition & Check for 2024
    const result2024 = await getSnowIceArea(start2024, end2024, mountStanley, '2024');
    if (result2024.initialSize === 0) {
      console.log('No data found for 2024.');
      console.log('C1');
      return;
    }
    if (result2024.count === 0) {
      console.log('No valid pixels for 2024 after cloud masking.');
      console.log('C2');
      return;
    }
    if (result2024.area === null) {
      console.log('Calculation failure for 2024 area.');
      console.log('C3');
      return;
    }

    // 5. Validation & Final Answer
    const area2020 = result2020.area;
    const area2024 = result2024.area;

    console.log(`2020 Snow/Ice Cover: ${area2020.toFixed(2)} sq km`);
    console.log(`2024 Snow/Ice Cover: ${area2024.toFixed(2)} sq km`);

    if (area2024 < area2020) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (error) {
    console.error("An error occurred:", error);
    if (error.message.includes('Image.select')) {
      console.log('D'); // Likely incorrect band name or collection issue
    } else if (error.message.includes('A map function must return an image.')) {
      console.log('D'); // Map function error
    } else {
      console.log('D'); // General error, potentially a GEE API issue or memory
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
